import 'dart:io';
import 'package:flutter_test/flutter_test.dart';

const _logo = 'https://onespace.live/assets/icon-512.png';

/// Every Supabase Auth template the dashboard can send, generated by
/// supabase/email-templates/build.py from one shell.
const _authTemplates = {
  'confirmation.html': ['{{ .ConfirmationURL }}', '{{ .Email }}'],
  'invite_user.html': ['{{ .ConfirmationURL }}'],
  'magic_link.html': ['{{ .ConfirmationURL }}'],
  'email_change.html': ['{{ .ConfirmationURL }}', '{{ .NewEmail }}'],
  'password_recovery.html': ['{{ .ConfirmationURL }}'],
  'reauthentication.html': ['{{ .Token }}'],
  'password_changed_notification.html': ['{{ .Email }}'],
  'email_changed_notification.html': ['{{ .OldEmail }}', '{{ .Email }}'],
};

void main() {
  test('every auth email and the invitation share one OneSpace brand', () {
    final sources = {
      for (final name in _authTemplates.keys)
        'supabase/email-templates/$name':
            File('supabase/email-templates/$name').readAsStringSync(),
      'supabase/functions/onespace-send-invitation/index.ts':
          File('supabase/functions/onespace-send-invitation/index.ts')
              .readAsStringSync(),
    };
    sources.forEach((path, source) {
      expect(source, contains('Two of Us. One Space'), reason: path);
      expect(source, isNot(contains('One Life. Two Places. One Space.')),
          reason: path);
      expect(source, contains(_logo), reason: path);
      expect(source, isNot(contains('raw.githubusercontent.com')), reason: path);
      expect(source, contains('mailto:support@onespace.live'), reason: path);
    });
  });

  test('auth templates keep the Supabase variables they need', () {
    _authTemplates.forEach((name, vars) {
      final html = File('supabase/email-templates/$name').readAsStringSync();
      for (final v in vars) {
        expect(html, contains(v), reason: '$name needs $v');
      }
    });
  });

  test('invitation is sent from the standard OneSpace sender', () {
    final source = File('supabase/functions/onespace-send-invitation/index.ts')
        .readAsStringSync();
    expect(source, contains('from:"OneSpace <support@onespace.live>"'));
    expect(source, contains('reply_to:"support@onespace.live"'));
  });
}
